package android.os; import java.util.*; public class Bundle {private final Map<String,Object> m=new LinkedHashMap<>(); public Set<String> keySet(){return m.keySet();} public Object get(String k){return m.get(k);} public void putInt(String k,int v){m.put(k,v);} public void putString(String k,String v){m.put(k,v);} public void putByteArray(String k,byte[] v){m.put(k,v);} public void putIntArray(String k,int[] v){m.put(k,v);}}